  1	#ifndef DSM_STORE_H
  2	#define DSM_STORE_H
  3	
  4	#include "common/record.h"
  5	
  6	#include <stddef.h>
  7	#include <stdint.h>
  8	
  9	/* A store file is one header followed by records, back to back:
 10	 *
 11	 *   [ header: 24 bytes ][ record 0: 48 ][ record 1: 48 ] ...
 12	 *
 13	 * Records are only ever added at the end. Nothing is rewritten in place.
 14	 *
 15	 * Durability today: store_append() hands the bytes to the kernel. It does
 16	 * not wait for them to reach the SD card (no fsync), so a power cut can
 17	 * still lose the most recent records. */
 18	
 19	#define DSM_STORE_MAGIC "DSKY"
 20	
 21	/* The first 24 bytes of every store file. */
 22	struct dsm_store_header {
 23	    char     magic[4];         /* "DSKY", no terminating zero */
 24	    uint16_t schema_ver;       /* DSM_SCHEMA_VER of the records inside */
 25	    uint16_t record_size;      /* sizeof(struct dsm_record) */
 26	    uint64_t created_real_ns;  /* CLOCK_REALTIME when the file was made */
 27	    uint32_t reserved;         /* always 0; puts crc32 last with no padding */
 28	    uint32_t crc32;            /* covers every byte before this field */
 29	};
 30	
 31	_Static_assert(sizeof(struct dsm_store_header) == 24,
 32	               "dsm_store_header must be exactly 24 bytes");
 33	_Static_assert(offsetof(struct dsm_store_header, crc32) == 20,
 34	               "crc32 must be the last 4 bytes of the header");
 35	
 36	enum store_status {
 37	    STORE_OK = 0,
 38	    STORE_ERR_IO,      /* a system call failed; errno says why */
 39	    STORE_ERR_FORMAT,  /* the file exists but is not a store file; untouched */
 40	    STORE_ERR_BADREC,  /* the record's CRC does not match; nothing written */
 41	    STORE_ERR_BROKEN,  /* an earlier write failed; no more appends */
 42	};
 43	
 44	/* Opaque: only store.c can see inside. */
 45	struct dsm_store;
 46	
 47	enum store_status store_open(const char *path, struct dsm_store **out);
 48	enum store_status store_append(struct dsm_store *s, const struct dsm_record *r);
 49	enum store_status store_close(struct dsm_store *s);
 50	
 51	#endif
  1	#include "store/store.h"
  2	#include "common/crc32.h"
  3	
  4	#include <errno.h>
  5	#include <fcntl.h>
  6	#include <stdbool.h>
  7	#include <stdlib.h>
  8	#include <string.h>
  9	#include <sys/stat.h>
 10	#include <time.h>
 11	#include <unistd.h>
 12	
 13	struct dsm_store {
 14	    int  fd;
 15	    bool broken;   /* a write failed, so we no longer know where the file ends */
 16	};
 17	
 18	/* write() can write fewer bytes than asked (disk nearly full, or a signal
 19	 * arrived), so keep going until everything is written or a real error. */
 20	static int write_all(int fd, const void *buf, size_t len)
 21	{
 22	    const unsigned char *p = buf;
 23	    while (len > 0) {
 24	        ssize_t n = write(fd, p, len);
 25	        if (n < 0) {
 26	            if (errno == EINTR)
 27	                continue;
 28	            return -1;
 29	        }
 30	        if (n == 0) {          /* never expected for a file; don't loop forever */
 31	            errno = EIO;
 32	            return -1;
 33	        }
 34	        p += n;
 35	        len -= (size_t)n;
 36	    }
 37	    return 0;
 38	}
 39	
 40	static uint64_t now_real_ns(void)
 41	{
 42	    struct timespec ts;
 43	    if (clock_gettime(CLOCK_REALTIME, &ts) != 0)
 44	        return 0;              /* 0 means "unknown"; the file still works */
 45	    return (uint64_t)ts.tv_sec * 1000000000u + (uint64_t)ts.tv_nsec;
 46	}
 47	
 48	static uint32_t header_crc(const struct dsm_store_header *h)
 49	{
 50	    return dsm_crc32(h, offsetof(struct dsm_store_header, crc32));
 51	}
 52	
 53	static enum store_status write_header(int fd)
 54	{
 55	    struct dsm_store_header h;
 56	    memset(&h, 0, sizeof h);
 57	    memcpy(h.magic, DSM_STORE_MAGIC, sizeof h.magic);
 58	    h.schema_ver = DSM_SCHEMA_VER;
 59	    h.record_size = (uint16_t)sizeof(struct dsm_record);
 60	    h.created_real_ns = now_real_ns();
 61	    h.crc32 = header_crc(&h);
 62	    return write_all(fd, &h, sizeof h) == 0 ? STORE_OK : STORE_ERR_IO;
 63	}
 64	
 65	/* Every check has to pass. If one fails this is not our file, and we
 66	 * refuse to touch it: it could be somebody else's data. */
 67	static enum store_status check_header(int fd, off_t size)
 68	{
 69	    struct dsm_store_header h;
 70	    if (size < (off_t)sizeof h)
 71	        return STORE_ERR_FORMAT;
 72	    if (pread(fd, &h, sizeof h, 0) != (ssize_t)sizeof h)
 73	        return STORE_ERR_IO;
 74	    if (memcmp(h.magic, DSM_STORE_MAGIC, sizeof h.magic) != 0
 75	        || h.crc32 != header_crc(&h)
 76	        || h.schema_ver != DSM_SCHEMA_VER
 77	        || h.record_size != sizeof(struct dsm_record))
 78	        return STORE_ERR_FORMAT;
 79	    return STORE_OK;
 80	}
 81	
 82	enum store_status store_open(const char *path, struct dsm_store **out)
 83	{
 84	    enum store_status st;
 85	    struct dsm_store *s = NULL;
 86	    struct stat sb;
 87	    int saved_errno;
 88	
 89	    *out = NULL;
 90	
 91	    /* O_APPEND: every write goes to the current end of the file.
 92	     * O_CLOEXEC: the fd is closed automatically if this process execs
 93	     * another program, so it can't leak into children. */
 94	    int fd = open(path, O_RDWR | O_CREAT | O_APPEND | O_CLOEXEC, 0644);
 95	    if (fd < 0)
 96	        return STORE_ERR_IO;
 97	
 98	    if (fstat(fd, &sb) != 0) {
 99	        st = STORE_ERR_IO;
100	        goto fail;
101	    }
102	
103	    /* Empty means we just created it (or a crash came before the header
104	     * was written), so it gets a header. Otherwise it must already be ours. */
105	    st = sb.st_size == 0 ? write_header(fd) : check_header(fd, sb.st_size);
106	    if (st != STORE_OK)
107	        goto fail;
108	
109	    s = malloc(sizeof *s);
110	    if (s == NULL) {
111	        st = STORE_ERR_IO;     /* errno is ENOMEM */
112	        goto fail;
113	    }
114	    s->fd = fd;
115	    s->broken = false;
116	    *out = s;
117	    return STORE_OK;
118	
119	fail:
120	    saved_errno = errno;       /* close() could overwrite the real reason */
121	    close(fd);
122	    errno = saved_errno;
123	    return st;
124	}
125	
126	enum store_status store_append(struct dsm_store *s, const struct dsm_record *r)
127	{
128	    if (s->broken)
129	        return STORE_ERR_BROKEN;
130	
131	    /* Recovery will cut the file off at the first bad record, so one bad
132	     * record let in here would cost every good record after it. */
133	    if (!record_intact(r))
134	        return STORE_ERR_BADREC;
135	
136	    /* If this fails part-way, part of a record may now be on disk, and
137	     * anything appended after it would be misaligned. Stop here instead. */
138	    if (write_all(s->fd, r, sizeof *r) != 0) {
139	        s->broken = true;
140	        return STORE_ERR_IO;
141	    }
142	    return STORE_OK;
143	}
144	
145	/* Accepts NULL, like free(), so cleanup code can call it unconditionally. */
146	enum store_status store_close(struct dsm_store *s)
147	{
148	    if (s == NULL)
149	        return STORE_OK;
150	    int rc = close(s->fd);
151	    free(s);
152	    return rc == 0 ? STORE_OK : STORE_ERR_IO;
153	}

