bool mlx_reply_ok(uint8_t addr, uint8_t cmd, const uint8_t reply[3]) { (void)addr; (void)cmd; (void)reply; return false; }
bool mlx_raw_to_mC(uint16_t raw, int32_t *mc) { (void)raw; (void)mc; return false; }
void mlx_fill(struct dsm_record *r, uint16_t obj_raw, uint16_t amb_raw) { (void)r; (void)obj_raw; (void)amb_raw; }
